INSERT INTO monster VALUES (593,'Unicorn','Celestial Charger, 7th-Level Cleric',NULL,'Large','Magical Beast',NULL,'8d10+7d8+75 (155 hp)','+4','60 ft. (12 squares)','24 (-1 size, +4 Dex, +6 natural, +5 bracers of armor +5), touch 13, flat-footed 20','+13','+24','Horn +22 melee (1d8+10)','Horn +22 melee (1d8+10) and 2 hooves +14 melee (1d4+3)','10 ft.','5 ft.','Turn undead 13/day, smite evil, spells','Damage reduction 10/magic, darkvision 60 ft., immunity to poison, charm, and compulsion, low-light vision, magic circle against evil, acid resistance 10, cold resistance 10, electricity resistance 10, scent, spell-like abilities, spell resistance 20, wild empathy','Fort +16, Ref +12, Will +15','Str 24, Dex 18, Con 20, Int 13, Wis 27, Cha 22','Concentration +11, Knowledge (nature) +9, Knowledge (religion) +8, Listen +15, Move Silently +12, Spellcraft +5, Spot +15, Survival +15 (+17 aboveground)*',NULL,'Alertness, Combat Casting, Extra Turning, Improved Turning, Run, Skill Focus (Survival)',NULL,'A chaotic good plane','Solitary','13','None','Always chaotic good','By character class','+8 (cohort)','Magic Circle Against Evil (Su), Smite Evil (Su), Wild Empathy (Ex)','7th-level cleric celestial charger; CR 13; Large magical beast; HD 8d10+7d8+75; hp 155; Init +4; Spd 60 ft. (12 squares); AC 24 (-1 size, +4 dex, +6 natural, +5 bracers of armor +5), touch 13, flat-footed 20; Base Atk +13; Grp +24; Atk +22 melee (1d8+10, horn); Full Atk +22 melee (1d8+10, horn) and +14 melee (1d4+3, 2 hooves); Space/Reach 10 ft./5 ft.; SA Turn undead 13/day, smite evil, spells; SQ Damage reduction 10/magic, darkvision 60 ft., immunity to poison, charm, and compulsion, low-light vision, magic circle against evil, acid resistance 10, cold resistance 10, electricity resistance 10, scent, spell-like abilities, spell resistance 20, wild empathy; AL CG; SV Fort +16, Ref +12, Will +15; Str 24, Dex 18, Con 20, Int 13, Wis 27, Cha 22\n\nSkills and Feats: Concentration +11, Knowledge (nature) +9, Knowledge (religion) +8, Listen +15, Move Silently +12, Spellcraft +5, Spot +15, Survival +15 (+17 aboveground)*; Alertness, Combat Casting, Extra Turning, Improved Turning, Run, Skill Focus (Survival)','\n      <div topic=\"Unicorn\" level=\"2\"><p><h2>Unicorn</h2></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n <td><b>Celestial Charger, 7th-Level Cleric</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n\n<td>Large Magical Beast<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n\n<td>8d10+7d8+75 (155 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n\n<td>+4<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n\n<td>60 ft. (12 squares)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n\n<td>24 (-1 size, +4 Dex, +6 natural, +5 <i>bracers of armor +5</i>), touch 13, flat-footed 20<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n\n<td>+13/+24<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n\n<td>Horn +22 melee (1d8+10)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n\n<td>Horn +22 melee (1d8+10) and 2 hooves +14 melee (1d4+3)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n\n<td>10 ft./5 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n\n<td>Turn undead 13/day, smite evil, spells<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n\n<td>Damage reduction 10/magic, darkvision 60 ft., immunity to poison, charm, and compulsion, low-light vision, magic circle against evil, acid resistance 10, cold resistance 10, electricity resistance 10, scent, spell-like abilities, spell resistance 20, wild empathy<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n\n<td>Fort +16, Ref +12, Will +15<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n\n<td>Str 24, Dex 18, Con 20, Int 13, Wis 27, Cha 22<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n\n<td>Concentration +11, Knowledge (nature) +9, Knowledge (religion) +8, Listen +15, Move Silently +12, Spellcraft +5, Spot +15, Survival +15 (+17 aboveground)*<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n\n<td>Alertness, Combat Casting, Extra Turning, Improved Turning, Run, Skill Focus (Survival)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n\n<td>A chaotic good plane<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n\n<td>Solitary<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n\n<td>13<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n\n<td>None<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n\n<td>Always chaotic good<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n\n<td>By character class<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n\n<td>+8 (cohort)<br/></td>\n\n</tr>\n</table><p>A unicorn has deep sea-blue, violet, brown, or fiery gold eyes. Males sport a white beard.</p><p>A typical adult unicorn grows to 8 feet in length, stands 5 feet high at the shoulder, and weighs 1,200 pounds. Females are slightly smaller and slimmer than males.</p><p>Unicorns speak Sylvan and Common.</p><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><p>Unicorns normally attack only when defending themselves or their forests. They either charge, impaling foes with their horns like lances, or strike with their hooves. The horn is a +3 magic weapon, though its power fades if removed from the unicorn.</p><div topic=\"Magic Circle Against Evil\" level=\"8\"><p><b>Magic Circle against Evil (Su):</b> This ability continuously duplicates the effect of the spell. A unicorn cannot suppress this ability.</p>\n</div><div topic=\"Spell-Like Abilities\" level=\"8\"><p><b>Spell-Like Abilities:</b> Unicorns can use <i>detect evil</i> at will as a free action.</p><p>Once per day a unicorn can use <i>greater teleport</i> to move anywhere within its home. It cannot teleport beyond the forest boundaries nor back from outside.</p><p>A unicorn can use <i>cure light wounds</i> three times per day and <i>cure moderate wounds</i> once per day (caster level 5th) by touching a wounded creature with its horn. Once per day it can use <i>neutralize poison</i> (DC 21, caster level 8th) with a touch of its horn. The save DC is Charisma-based.</p>\n</div><div topic=\"Wild Empathy\" level=\"8\"><p><b>Wild Empathy (Ex):</b> This power works like the druid\'s wild empathy class feature, except that a unicorn has a +6 racial bonus on the check.</p>\n</div><div topic=\"Skills\" level=\"8\"><p><b>Skills:</b> Unicorns have a +4 racial bonus on Move Silently checks. *Unicorns have a +3 competence bonus on Survival checks within the boundaries of their forest.</p><p/>\n</div>\n</div><div topic=\"Celestial Charger\" level=\"3\"><p><h3>Celestial Charger</h3></p><p>The celestial charger described here is an 8 HD celestial unicorn with seven levels of cleric.</p><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><p>The save DC for this celestial charger\'s <i>neutralize poison</i> ability (DC 20) is adjusted for its greater Hit Dice and altered Charisma score.</p><p>A celestial charger\'s natural weapons are treated as magic weapons for the purpose of overcoming damage reduction.</p><div topic=\"Smite Evil\" level=\"8\"><p><b>Smite Evil (Su):</b> Once per day a celestial charger can make a normal melee attack to deal 15 points of extra damage against an evil foe.</p><p><i>Cleric Spells Prepared</i> (6/7/6/5/4; save DC 18 + spell level): 0- <i>detect magic</i>,  <i>detect poison</i> (2), <i>light</i>,  <i>virtue</i> (2); 1st-<i>bless</i> (2), <i>calm animals*</i>,  <i>obscuring mist</i>,  <i>remove fear</i>,  <i>sanctuary</i>,  <i>shield of faith</i>; 2nd-<i>aid</i>* (2), <i>animal messenger</i>,  <i>lesser restoration</i>,  <i>remove paralysis</i>,  <i>shield other</i>; 3rd-<i>prayer</i>,  <i>protection from energy</i>,  <i>remove curse</i>,  <i>searing light</i> (2); 4th-<i>air walk</i>,  <i>divine power</i>,  <i>holy smite*</i>,  <i>restoration</i>.</p><p>*Domain spell. Domains: Animal and Good.</p><p/>\n</div>\n</div>\n</div>\n</div>\n    ','SRD 3.5 MonstersT-Z');
INSERT INTO monster VALUES (594,'Vampire','Vampire Spawn',NULL,'Medium','Undead',NULL,'4d12+3 (29 hp)','+6','30 ft. (6 squares)','15 (+2 Dex, +3 natural), touch 12, flat-footed 13','+2','+5','Slam +5 melee (1d6+4 plus energy drain)','Slam +5 melee (1d6+4 plus energy drain)','5 ft.','5 ft.','Blood drain, domination, energy drain','+2 turn resistance, damage reduction 5/silver, darkvision 60 ft., fast healing 2, gaseous form, cold resistance 10, electricity resistance 10, spider climb, undead traits','Fort +1, Ref +5, Will +5','Str 16, Dex 14, Con -, Int 13, Wis 13, Cha 14','Bluff +6, Climb +8, Craft or Profession (any one) +4, Diplomacy +4, Hide +10, Jump +8, Listen +11, Move Silently +10, Search +8, Sense Motive +11, Spot +11','Alertness, Improved Initiative, Lightning Reflexes','Skill Focus (selected Craft or Profession skill), Toughness',NULL,'Any','Solitary or pack (2-5)','4','Standard','Always evil (any)','-','-','Blood Drain (Ex), Domination (Su), Energy Drain (Su), Fast Healing (Ex), Gaseous Form (Su), Spider Climb (Ex)','Vampire spawn; CR 4; Medium undead; HD 4d12+3; hp 29; Init +6; Spd 30 ft. (6 squares); AC 15 (+2 dex, +3 natural), touch 12, flat-footed 13; Base Atk +2; Grp +5; Atk +5 melee (1d6+4 plus energy drain, slam); Full Atk +5 melee (1d6+4 plus energy drain, slam); Space/Reach 5 ft./5 ft.; SA Blood drain, domination, energy drain; SQ +2 turn resistance, damage reduction 5/silver, darkvision 60 ft., fast healing 2, gaseous form, cold resistance 10, electricity resistance 10, spider climb, undead traits; AL NE; SV Fort +1, Ref +5, Will +5; Str 16, Dex 14, Con -, Int 13, Wis 13, Cha 14\n\nSkills and Feats: Bluff +6, Climb +8, Craft or Profession (any one) +4, Diplomacy +4, Hide +10, Jump +8, Listen +11, Move Silently +10, Search +8, Sense Motive +11, Spot +11; Alertness, Improved Initiative, Lightning Reflexes, Skill Focus (selected Craft or Profession skill), Toughness','\n      <div topic=\"Vampire Spawn\" level=\"3\"><p><h3>Vampire Spawn</h3></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td><b>Vampire Spawn</b><br/></td>\n\n</tr><tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Medium Undead<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>4d12+3 (29 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>+6<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>30 ft. (6 squares)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>15 (+2 Dex, +3 natural), touch 12, flat-footed 13<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+2/+5<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>Slam +5 melee (1d6+4 plus energy drain)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>Slam +5 melee (1d6+4 plus energy drain)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>5 ft./5 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>Blood drain, domination, energy drain<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>+2 turn resistance, damage reduction 5/silver, darkvision 60 ft., fast healing 2, gaseous form, cold resistance 10, electricity resistance 10, spider climb, undead traits<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +1, Ref +5, Will +5<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str 16, Dex 14, Con -, Int 13, Wis 13, Cha 14<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n<td>Bluff +6, Climb +8, Craft or Profession (any one) +4, Diplomacy +4, Hide +10, Jump +8, Listen +11, Move Silently +10, Search +8, Sense Motive +11, Spot +11<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>Alertness <sup>B</sup>, Improved Initiative <sup>B</sup>, Lightning Reflexes <sup>B</sup>, Skill Focus (selected Craft or Profession skill), Toughness<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>Any<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Solitary or pack (2-5)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>4<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n<td>Standard<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n<td>Always evil (any)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>-<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>-<br/></td>\n\n</tr>\n</table><p>Vampire spawn are undead creatures that come into being when vampires slay mortals. Like their creators, spawn remain bound to their coffins and to the soil of their graves. Vampire spawn appear much as they did in life, although their features are often hardened, with a predatory look.</p><p>Vampire spawn speak Common.</p><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><p>Vampire spawn use their inhuman strength when engaging mortals, hammering their foes with powerful blows and dashing them against rocks or walls. They also use their gaseous form and flight abilities to strike where opponents are most vulnerable.</p><div topic=\"Blood Drain\" level=\"8\"><p><b>Blood Drain (Ex):</b> A vampire spawn can suck blood from a living victim with its fangs by making a successful grapple check. If it pins the foe, it drains blood, dealing 1d4 points of Constitution drain each round. On each such successful drain attack, the vampire spawn gains 5 temporary hit pints.</p>\n</div><div topic=\"Domination\" level=\"8\"><p><b>Domination (Su):</b> A vampire spawn can crush an opponent\'s will just by looking onto his or her eyes. This is similar to a gaze attack, except that the vampire must take a standard action, and those merely looking at it are not affected. Anyone the vampire targets must succeed on a DC 14 Will save or fall instantly under the vampire\'s influence as though by a <i>dominate person</i> spell from a 5thlevel caster. The ability has a range of 30 feet. The save DC is Charisma-based.</p>\n</div><div topic=\"Energy Drain\" level=\"8\"><p><b>Energy Drain (Su):</b> Living creatures hit by a vampire spawn\'s slam attack gain one negative level. The DC is 14 for the Fortitude save to remove a negative level. The save DC is Charisma-based. For each such negative level bestowed, the vampire spawn gains 5 temporary hit points.</p>\n</div><div topic=\"Fast Healing\" level=\"8\"><p><b>Fast Healing (Ex):</b> A vampire spawn heals 2 points of damage each round so long as it has at least 1 hit point. If reduced to 0 hit points in combat, it automatically assumes gaseous form and attempts to escape. It must reach its coffin home within 2 hours or be utterly destroyed. (It can travel up to nine miles in 2 hours.) Once at rest in its coffin, it is helpless. It regains 1 hit point after 1 hour, then is no longer helpless and resumes healing at the rate of 2 hit points per round.</p>\n</div><div topic=\"Gaseous Form\" level=\"8\"><p><b>Gaseous Form (Su):</b> As a standard action, a vampire spawn can assume <i>gaseous form</i> at will as the spell (caster level 6th), but it can remain gaseous indefinitely and has a fly speed of 20 feet with perfect maneuverability.</p>\n</div><div topic=\"Spider Climb\" level=\"8\"><p><b>Spider Climb (Ex):</b> A vampire spawn can climb sheer surfaces as though with a <i>spider climb</i> spell.</p>\n</div><div topic=\"Skills\" level=\"8\"><p><b>Skills:</b> Vampire spawn have a +4 racial bonus on Bluff, Hide, Listen, Move Silently, Search, Sense Motive, and Spot checks.</p>\n</div>\n</div><div topic=\"Vampire Spawn Weaknesses\" level=\"4\"><p><h4>Vampire Spawn Weaknesses</h4></p><p>Vampire spawn are vulnerable to all attacks and effects that repel or slay vampires. For details, see the Vampire entry.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 MonstersT-Z');
INSERT INTO monster VALUES (595,'Vargouille','Vargouille',NULL,'Small','Outsider','Evil, Extraplanar','1d8+1 (5 hp)','+1','Fly 30 ft. (good) (6 squares)','12 (+1 size, +1 Dex), touch 11, flat-footed 11','+1','-3','Bite +3 melee (1d4 plus poison)','Bite +3 melee (1d4 plus poison)','5 ft.','5 ft.','Shriek, kiss, poison','Darkvision 60 ft.','Fort +3, Ref +3, Will +3','Str 10, Dex 13, Con 12, Int 5, Wis 12, Cha 8','Hide +9, Intimidate +3, Listen +5, Move Silently +5, Spot +5',NULL,'Weapon Finesse',NULL,'An evil-aligned plane','Cluster (2-5) or mob (6-11)','2','None','Always neutral evil','2-3 HD (Small)','-','Kiss (Su), Poison (Ex), Shriek (Su)','Vargouille; CR 2; Small outsider (evil, extraplanar); HD 1d8+1; hp 5; Init +1; Spd Fly 30 ft. (good) (6 squares); AC 12 (+1 size, +1 dex), touch 11, flat-footed 11; Base Atk +1; Grp -3; Atk +3 melee (1d4 plus poison, bite); Full Atk +3 melee (1d4 plus poison, bite); Space/Reach 5 ft./5 ft.; SA Shriek, kiss, poison; SQ Darkvision 60 ft.; AL NE; SV Fort +3, Ref +3, Will +3; Str 10, Dex 13, Con 12, Int 5, Wis 12, Cha 8\n\nSkills and Feats: Hide +9, Intimidate +3, Listen +5, Move Silently +5, Spot +5; Weapon Finesse','\n      <div topic=\"Vargouille\" level=\"2\"><p><h2>Vargouille</h2></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td><b>Vargouille</b><br/></td>\n\n</tr><tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Small Outsider (Evil, Extraplanar)<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>1d8+1 (5 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>+1<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>Fly 30 ft. (good) (6 squares)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>12 (+1 size, +1 Dex), touch 11, flat-footed 11<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+1/-3<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>Bite +3 melee (1d4 plus poison)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>Bite +3 melee (1d4 plus poison)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>5 ft./5 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>Shriek, kiss, poison<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>Darkvision 60 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +3, Ref +3, Will +3<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str 10, Dex 13, Con 12, Int 5, Wis 12, Cha 8<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n<td>Hide +9, Intimidate +3, Listen +5, Move Silently +5, Spot +5<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>Weapon Finesse<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>An evil-aligned plane<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Cluster (2-5) or mob (6-11)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n<td>None<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n<td>Always neutral evil<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>2-3 HD (Small)<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>-<br/></td>\n\n</tr>\n</table><p>A vargouille is slightly larger than a human head, about 18 inches high, with a wingspan of 4 feet. It weighs about 10 pounds.</p><p>Vargouilles speak Infernal.</p><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><p>Vargouilles attack by biting with their jagged teeth. Their special attacks make them even more dangerous. A vargouille\'s natural weapons, as well as any weapons it wields, are treated as evil-aligned for the purpose of overcoming damage reduction.</p><div topic=\"Shriek\" level=\"8\"><p><b>Shriek (Su):</b> Instead of biting, a vargouille can open its distended mouth and let out a terrible shriek. Those within 60 feet (except other vargouilles) who hear the shriek and can clearly see the creature must succeed on a DC 12 Fortitude save or be paralyzed with fear for 2d4 rounds or until the monster attacks them, goes out of range, or leaves their sight. A paralyzed creature is susceptible to the vargouille\'s kiss (see below). A creature that successfully saves cannot be affected again by the same vargouille\'s shriek for 24 hours. The shriek is a mind-affecting fear effect. The save DC is Constitution-based and includes a +1 racial bonus.</p>\n</div><div topic=\"Kiss\" level=\"8\"><p><b>Kiss (Su):</b> A vargouille can kiss a paralyzed target with a successful melee touch attack. An affected opponent must succeed on a DC 15 Fortitude save or begin a terrible transformation that turns the creature into a vargouille within 24 hours (and often much sooner; roll 1d6 separately for each phase of the transformation).</p><p>First, over a period of 1d6 hours, all the victim\'s hair falls out. Within another 1d6 hours thereafter, the ears grow into leathery wings, tentacles sprout on the chin and scalp, and the teeth become long, pointed fangs. During the next 1d6 hours, the victim takes Intelligence drain and Charisma drain equal to 1 point per hour (to a minimum of 3). The transformation is complete 1d6 hours later, when the head breaks free of the body (which promptly dies) and becomes a vargouille. This transformation is interrupted by sunlight, and even a <i>daylight</i> spell can delay death, but to reverse the transformation requires <i>remove disease</i>. The save DC is Constitution-based and includes a +4 racial bonus.</p>\n</div><div topic=\"Poison\" level=\"8\"><p><b>Poison (Ex):</b> Injury, Fortitude DC 12 or be unable to heal the vargouille\'s bite damage naturally or magically. A <i>neutralize poison</i> or <i>heal</i> spell removes the effect, while <i>delay poison</i> allows magical healing. The save DC is Constitution-based and includes a +1 racial bonus.</p><p/>\n</div>\n</div>\n</div>\n    ','SRD 3.5 MonstersT-Z');
INSERT INTO monster VALUES (596,'Wight','Wight',NULL,'Medium','Undead',NULL,'4d12 (26 hp)','+1','30 ft. (6 squares)','15 (+1 Dex, +4 natural), touch 11, flat-footed 14','+2','+3','Slam +3 melee (1d4+1 plus energy drain)','Slam +3 melee (1d4+1 plus energy drain)','5 ft.','5 ft.','Create spawn, energy drain','Darkvision 60 ft., undead traits','Fort +1, Ref +2, Will +5','Str 12, Dex 12, Con -, Int 11, Wis 13, Cha 15','Hide +8, Listen +7, Move Silently +16, Spot +7',NULL,'Alertness, Blind-Fight',NULL,'Any','Solitary, pair, gang (3-5), or pack (6-11)','3','None','Always lawful evil','5-8 HD (Medium)','-','Create Spawn (Su), Energy Drain (Su)','Wight; CR 3; Medium undead; HD 4d12; hp 26; Init +1; Spd 30 ft. (6 squares); AC 15 (+1 dex, +4 natural), touch 11, flat-footed 14; Base Atk +2; Grp +3; Atk +3 melee (1d4+1 plus energy drain, slam); Full Atk +3 melee (1d4+1 plus energy drain, slam); Space/Reach 5 ft./5 ft.; SA Create spawn, energy drain; SQ Darkvision 60 ft., undead traits; AL LE; SV Fort +1, Ref +2, Will +5; Str 12, Dex 12, Con -, Int 11, Wis 13, Cha 15\n\nSkills and Feats: Hide +8, Listen +7, Move Silently +16, Spot +7; Alertness, Blind-Fight','\n      <div topic=\"Wight\" level=\"2\"><p><h2>Wight</h2></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td><b>Wight</b><br/></td>\n\n</tr><tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Medium Undead<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>4d12 (26 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>+1<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>30 ft. (6 squares)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>15 (+1 Dex, +4 natural), touch 11, flat-footed 14<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+2/+3<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>Slam +3 melee (1d4+1 plus energy drain)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>Slam +3 melee (1d4+1 plus energy drain)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>5 ft./5 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>Create spawn, energy drain<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>Darkvision 60 ft., undead traits<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +1, Ref +2, Will +5<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str 12, Dex 12, Con -, Int 11, Wis 13, Cha 15<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n<td>Hide +8, Listen +7, Move Silently +16, Spot +7<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>Alertness, Blind-Fight<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>Any<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Solitary, pair, gang (3-5), or pack (6-11)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>3<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n<td>None<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n<td>Always lawful evil<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>5-8 HD (Medium)<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>-<br/></td>\n\n</tr>\n</table><p>A wight\'s appearance is a weird and twisted reflection of the form it had in life. A wight is about the height and weight of a human.</p><p>Wights speak Common.</p><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><p>Wights attack by hammering with their fists.</p><div topic=\"Create Spawn\" level=\"8\"><p><b>Create Spawn (Su):</b> Any humanoid slain by a wight becomes a wight in 1d4 rounds. Spawn are under the command of the wight that created them and remain enslaved until its death. They do not possess any of the abilities they had in life.</p>\n</div><div topic=\"Energy Drain\" level=\"8\"><p><b>Energy Drain (Su):</b> Living creatures hit by a wight\'s slam attack gain one negative level. The DC is 14 for the Fortitude save to remove a negative level. The save DC is Charisma-based. For each such negative level bestowed, the wight gains 5 temporary hit points.</p>\n</div><div topic=\"Skills\" level=\"8\"><p><b>Skills:</b> Wights have a +8 racial bonus on Move Silently checks.</p><p/>\n</div>\n</div>\n</div>\n    ','SRD 3.5 MonstersT-Z');
INSERT INTO monster VALUES (597,'Will-O\'-Wisp','Will-O\'-Wisp',NULL,'Small','Aberration','Air','9d8 (40 hp)','+13','Fly 50 ft. (perfect) (10 squares)','29 (+1 size, +9 Dex, +9 deflection), touch 29, flat-footed 20','+6','-3','Shock +16 melee touch (2d8 electricity)','Shock +16 melee touch (2d8 electricity)','5 ft.','5 ft.','-','Darkvision 60 ft., immunity to magic, natural invisibility','Fort +3, Ref +12, Will +9','Str 1, Dex 29, Con 10, Int 15, Wis 16, Cha 12','Bluff +13, Diplomacy +3, Disguise +1 (+3 acting), Intimidate +3, Listen +17, Search +14, Spot +17, Survival +3 (+5 following tracks)','Weapon Finesse','Alertness, Blind-Fight, Dodge, Improved Initiative',NULL,'Temperate marshes','Solitary, pair, or string (3-4)','6','1/10 coins; 50% goods; 50% items','Usually chaotic evil','10-18 HD (Small)','-','Immunity to Magic (Ex), Natural Invisibility (Ex)','Will-o\'-wisp; CR 6; Small aberration (air); HD 9d8; hp 40; Init +13; Spd Fly 50 ft. (perfect) (10 squares); AC 29 (+1 size, +9 dex, +9 deflection), touch 29, flat-footed 20; Base Atk +6; Grp -3; Atk +16 melee (2d8 electricity, shock); Full Atk +16 melee (2d8 electricity, shock); Space/Reach 5 ft./5 ft.; SA -; SQ Darkvision 60 ft., immunity to magic, natural invisibility; AL CE; SV Fort +3, Ref +12, Will +9; Str 1, Dex 29, Con 10, Int 15, Wis 16, Cha 12\n\nSkills and Feats: Bluff +13, Diplomacy +3, Disguise +1 (+3 acting), Intimidate +3, Listen +17, Search +14, Spot +17, Survival +3 (+5 following tracks); Alertness, Blind-Fight, Dodge, Improved Initiative, Weapon Finesse','\n      <div topic=\"Will-O\'-Wisp\" level=\"2\"><p><h2>Will-O\'-Wisp</h2></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td><b>Will-O\'-Wisp</b><br/></td>\n\n</tr><tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Small Aberration (Air)<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>9d8 (40 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>+13<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>Fly 50 ft. (perfect) (10 squares)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>29 (+1 size, +9 Dex, +9 deflection), touch 29, flat-footed 20<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+6/-3<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>Shock +16 melee touch (2d8 electricity)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>Shock +16 melee touch (2d8 electricity)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>5 ft./5 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>-<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>Darkvision 60 ft., immunity to magic, natural invisibility<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +3, Ref +12, Will +9<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str 1, Dex 29, Con 10, Int 15, Wis 16, Cha 12<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n<td>Bluff +13, Diplomacy +3, Disguise +1 (+3 acting), Intimidate +3, Listen +17, Search +14, Spot +17, Survival +3 (+5 following tracks)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>Alertness, Blind-Fight, Dodge, Improved Initiative, Weapon Finesse <sup>B</sup><br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>Temperate marshes<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Solitary, pair, or string (3-4)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>6<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n<td>1/10 coins; 50% goods; 50% items<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n<td>Usually chaotic evil<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>10-18 HD (Small)<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>-<br/></td>\n\n</tr>\n</table><p>Will-o\'-wisps can be yellow, white, green, or blue. They are easily mistaken for lanterns, especially in the foggy marshes and swamps where they reside. A will-o\'-wisp\'s body is a globe of spongy material about 1 foot across and weighing about 3 pounds, and its glowing body sheds as much light as a torch.</p><p>Will-o\'-wisps speak Common and Auran. They have no vocal apparatus but can vibrate to create a voice with a ghostly sound.</p><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><p>Will-o\'-wisps usually avoid combat. They prefer to confuse and bewilder adventurers, luring them into morasses or other hazardous places. When they are forced to fight, they loose small electrical shocks, which act as melee touch attacks.</p><div topic=\"Immunity to Magic\" level=\"8\"><p><b>Immunity to Magic (Ex):</b> A will-o\'-wisp is immune to most spells or spell-like abilities that allow spell resistance, except <i>magic missile</i> and <i>maze</i>.</p>\n</div><div topic=\"Natural Invisibility\" level=\"8\"><p><b>Natural Invisibility (Ex):</b> A startled or frightened will-o\'-wisp can extinguish its glow, effectively becoming invisible as the spell.</p><p/>\n</div>\n</div>\n</div>\n    ','SRD 3.5 MonstersT-Z');
INSERT INTO monster VALUES (598,'Winter Wolf','Winter Wolf',NULL,'Large','Magical Beast','Cold','6d10+18 (51 hp)','+5','50 ft. (10 squares)','15 (-1 size, +1 Dex, +5 natural), touch 10, flat-footed 14','+6','+14','Bite +9 melee (1d8+6 plus 1d6 cold)','Bite +9 melee (1d8+6 plus 1d6 cold)','10 ft.','5 ft.','Breath weapon, freezing bite, trip','Darkvision 60 ft., immunity to cold, low-light vision, scent, vulnerability to fire','Fort +8, Ref +6, Will +3','Str 18, Dex 13, Con 16, Int 9, Wis 13, Cha 10','Hide -1*, Listen +6, Move Silently +7, Spot +6, Survival +1*',NULL,'Alertness, Improved Initiative, Track',NULL,'Cold forests','Solitary, pair, or pack (3-5)','5','1/10 coins; 50% goods; 50% items','Usually neutral evil','7-9 HD (Large); 10-18 HD (Huge)','+3 (cohort)','Breath Weapon (Su), Freezing Bite (Su), Trip (Ex)','Winter wolf; CR 5; Large magical beast (cold); HD 6d10+18; hp 51; Init +5; Spd 50 ft. (10 squares); AC 15 (-1 size, +1 dex, +5 natural), touch 10, flat-footed 14; Base Atk +6; Grp +14; Atk +9 melee (1d8+6 plus 1d6 cold, bite); Full Atk +9 melee (1d8+6 plus 1d6 cold, bite); Space/Reach 10 ft./5 ft.; SA Breath weapon, freezing bite, trip; SQ Darkvision 60 ft., immunity to cold, low-light vision, scent, vulnerability to fire; AL NE; SV Fort +8, Ref +6, Will +3; Str 18, Dex 13, Con 16, Int 9, Wis 13, Cha 10\n\nSkills and Feats: Hide -1*, Listen +6, Move Silently +7, Spot +6, Survival +1*; Alertness, Improved Initiative, Track','\n      <div topic=\"Winter Wolf\" level=\"2\"><p><h2>Winter Wolf</h2></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td><b>Winter Wolf</b><br/></td> \n</tr><tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Large Magical Beast (Cold)<br/></td> \n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>6d10+18 (51 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>+5<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>50 ft. (10 squares)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>15 (-1 size, +1 Dex, +5 natural), touch 10, flat-footed 14<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+6/+14<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>Bite +9 melee (1d8+6 plus 1d6 cold)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>Bite +9 melee (1d8+6 plus 1d6 cold)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>10 ft./5 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>Breath weapon, freezing bite, trip<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>Darkvision 60 ft., immunity to cold, low-light vision, scent, vulnerability to fire<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +8, Ref +6, Will +3<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str 18, Dex 13, Con 16, Int 9, Wis 13, Cha 10<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n<td>Hide -1*, Listen +6, Move Silently +7, Spot +6, Survival +1*<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>Alertness, Improved Initiative, Track<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>Cold forests<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Solitary, pair, or pack (3-5)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>5<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n<td>1/10 coins; 50% goods; 50% items<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n<td>Usually neutral evil<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>7-9 HD (Large); 10-18 HD (Huge)<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>+3 (cohort)<br/></td>\n\n</tr>\n</table><p>A winter wolf grows about 8 feet long and stands about 4-1/2 feet at the shoulder. It weighs about 450 pounds.</p><p>Winter wolves can speak Giant and Common.</p><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><p>Winter wolves typically hunt in packs. Their size, cunning, and formidable breath weapon allow them to hunt and kill creatures much larger than themselves. A pack usually circles an opponent, each wolf attacking in turn to exhaust it. If they\'re in a hurry, white wolves try to pin their foes.</p><div topic=\"Breath Weapon\" level=\"8\"><p><b>Breath Weapon (Su):</b> 15-foot cone, once every 1d4 rounds, damage 4d6 cold, Reflex DC 16 half. The save DC is Constitution-based.</p>\n</div><div topic=\"Freezing Bite\" level=\"8\"><p><b>Freezing Bite (Su):</b> A winter wolf deals an extra 1d6 points of cold damage every time it bites an opponent, as if its bite were a frost weapon.</p>\n</div><div topic=\"Trip\" level=\"8\"><p><b>Trip (Ex):</b> A winter wolf that hits with a bite attack can attempt to trip the opponent (+8 check modifier) as a free action without making a touch attack or provoking an attack of opportunity. If the attempt fails, the opponent cannot react to trip the winter wolf.</p>\n</div><div topic=\"Skills\" level=\"8\"><p><b>Skills:</b> Winter wolves have a +1 racial bonus on Listen, Move Silently, and Spot checks. Winter wolves have a +2 racial bonus on Hide checks. *Their natural coloration grants them a +7 racial bonus on Hide checks in areas of snow and ice. A winter wolf has a +4 racial bonus on Survival checks when tracking by scent.</p><p/>\n</div>\n</div>\n</div>\n    ','SRD 3.5 MonstersT-Z');
INSERT INTO monster VALUES (599,'Worg','Worg',NULL,'Medium','Magical Beast',NULL,'4d10+8 (30 hp)','+2','50 ft. (10 squares)','14 (+2 Dex, +2 natural), touch 12, flat-footed 12','+4','+7','Bite +7 melee (1d6+4)','Bite +7 melee (1d6+4)','5 ft.','5 ft.','Trip','Darkvision 60 ft., low-light vision, scent','Fort +6, Ref +6, Will +3','Str 17, Dex 15, Con 15, Int 6, Wis 14, Cha 10','Hide +4, Listen +6, Move Silently +6, Spot +6, Survival +2*',NULL,'Alertness, Track',NULL,'Temperate plains','Solitary, pair, or pack (6-11)','2','1/10 coins; 50% goods; 50% items','Usually neutral evil','5-6 HD (Medium); 7-12 HD (Large)','+1 (cohort)','Trip (Ex)','Worg; CR 2; Medium magical beast; HD 4d10+8; hp 30; Init +2; Spd 50 ft. (10 squares); AC 14 (+2 dex, +2 natural), touch 12, flat-footed 12; Base Atk +4; Grp +7; Atk +7 melee (1d6+4, bite); Full Atk +7 melee (1d6+4, bite); Space/Reach 5 ft./5 ft.; SA Trip; SQ Darkvision 60 ft., low-light vision, scent; AL NE; SV Fort +6, Ref +6, Will +3; Str 17, Dex 15, Con 15, Int 6, Wis 14, Cha 10\n\nSkills and Feats: Hide +4, Listen +6, Move Silently +6, Spot +6, Survival +2*; Alertness, Track','\n      <div topic=\"Worg\" level=\"2\"><p><h2>Worg</h2></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td><b>Worg</b><br/></td> \n</tr><tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Medium Magical Beast<br/></td> \n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>4d10+8 (30 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>+2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>50 ft. (10 squares)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>14 (+2 Dex, +2 natural), touch 12, flat-footed 12<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+4/+7<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>Bite +7 melee (1d6+4)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>Bite +7 melee (1d6+4)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>5 ft./5 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>Trip<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>Darkvision 60 ft., low-light vision, scent<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +6, Ref +6, Will +3<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str 17, Dex 15, Con 15, Int 6, Wis 14, Cha 10<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n<td>Hide +4, Listen +6, Move Silently +6, Spot +6, Survival +2*<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>Alertness, Track<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>Temperate plains<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Solitary, pair, or pack (6-11)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n<td>1/10 coins; 50% goods; 50% items<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n<td>Usually neutral evil<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>5-6 HD (Medium); 7-12 HD (Large)<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>+1 (cohort)<br/></td>\n\n</tr>\n</table><p>A typical worg has gray or black fur, grows to 5 feet long and stands 3 feet tall at the shoulder. It weighs 300 pounds.</p><p>More intelligent than their smaller cousins, worgs speak their own language. Some can also speak Common and Goblin.</p><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><p>Mated pairs or packs work together to bring down large game, while lone worgs usually chase down creatures smaller than themselves. Both often use hit-and-run tactics to exhaust their quarry. A pack usually circles a larger opponent: Each wolf attacks in turn, biting and retreating, until the creature is exhausted, at which point the pack moves in for the kill. If they get impatient or heavily outnumber the opponent, worgs attempt to pin it.</p><div topic=\"Trip\" level=\"8\"><p><b>Trip (Ex):</b> A worg that hits with a bite attack can attempt to trip the opponent (+3 check modifier) as a free action without making a touch attack or provoking an attack of opportunity. If the attempt fails, the opponent cannot react to trip the worg.</p>\n</div><div topic=\"Skills\" level=\"8\"><p><b>Skills:</b> A worg has a +1 racial bonus on Listen, Move Silently, and Spot checks, and a +2 racial bonus on Hide checks. *A worg has a +4 racial bonus on Survival checks when tracking by scent.</p><p/>\n</div>\n</div>\n</div>\n    ','SRD 3.5 MonstersT-Z');
INSERT INTO monster VALUES (600,'Wraith','Wraith',NULL,'Medium','Undead','Incorporeal','5d12 (32 hp)','+7','Fly 60 ft. (good) (12 squares)','15 (+3 Dex, +2 deflection), touch 15, flat-footed 12','+2','-','Incorporeal touch +5 melee (1d4 plus 1d6 Constitution drain)','Incorporeal touch +5 melee (1d4 plus 1d6 Constitution drain)','5 ft.','5 ft.','Constitution drain, create spawn','Darkvision 60 ft., daylight powerlessness, incorporeal traits, +2 turn resistance, undead traits, unnatural aura','Fort +1, Ref +4, Will +6','Str -, Dex 16, Con -, Int 14, Wis 14, Cha 15','Diplomacy +6, Hide +11, Intimidate +10, Listen +12, Search +10, Sense Motive +8, Spot +12, Survival +2 (+4 following tracks)','Alertness, Improved Initiative','Blind-Fight, Combat Reflexes',NULL,'Any','Solitary, gang (2-5), or pack (6-11)','5','None','Always lawful evil','6-10 HD (Medium)','-','Constitution Drain (Su), Create Spawn (Su), Daylight Powerlessness (Ex), Unnatural Aura (Su)','Wraith; CR 5; Medium undead (incorporeal); HD 5d12; hp 32; Init +7; Spd Fly 60 ft. (good) (12 squares); AC 15 (+3 dex, +2 deflection), touch 15, flat-footed 12; Base Atk +2; Grp -; Atk +5 melee (1d4 plus 1d6 Constitution drain, incorporeal touch); Full Atk +5 melee (1d4 plus 1d6 Constitution drain, incorporeal touch); Space/Reach 5 ft./5 ft.; SA Constitution drain, create spawn; SQ Darkvision 60 ft., daylight powerlessness, incorporeal traits, +2 turn resistance, undead traits, unnatural aura; AL LE; SV Fort +1, Ref +4, Will +6; Str -, Dex 16, Con -, Int 14, Wis 14, Cha 15\n\nSkills and Feats: Diplomacy +6, Hide +11, Intimidate +10, Listen +12, Search +10, Sense Motive +8, Spot +12, Survival +2 (+4 following tracks); Alertness, Blind-Fight, Combat Reflexes, Improved Initiative','\n      <div topic=\"Wraith\" level=\"2\"><p><h2>Wraith</h2></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td><b>Wraith</b><br/></td>\n\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Medium Undead (Incorporeal)<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>5d12 (32 hp)<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>+7<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>Fly 60 ft. (good) (12 squares)<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>15 (+3 Dex, +2 deflection), touch 15, flat-footed 12<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+2/-<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>Incorporeal touch +5 melee (1d4 plus 1d6 Constitution drain)<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>Incorporeal touch +5 melee (1d4 plus 1d6 Constitution drain)<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>5 ft./5 ft.<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>Constitution drain, create spawn<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>Darkvision 60 ft., daylight powerlessness, incorporeal traits, +2 turn resistance, undead traits, unnatural aura<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +1, Ref +4, Will +6<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str -, Dex 16, Con -, Int 14, Wis 14, Cha 15<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n<td>Diplomacy +6, Hide +11, Intimidate +10, Listen +12, Search +10, Sense Motive +8, Spot +12, Survival +2 (+4 following tracks)<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>Alertness <sup>B</sup>, Blind-Fight, Combat Reflexes, Improved Initiative <sup>B</sup><br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>Any<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Solitary, gang (2-5), or pack (6-11)<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>5<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n<td>None<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n<td>Always lawful evil<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>6-10 HD (Medium)<br/></td>\n\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>-<br/></td>\n\n\n</tr>\n</table><p>Wraiths are incorporeal creatures born of evil and darkness. In some cases, the grim silhouette of a wraith might appear armored or outfitted with weapons. This appearance does not affect the creature\'s AC or combat abilities but only reflects the shape it had in life.</p><p>A wraith is about as tall as a human, while a dread wraith is roughly the size of an ogre. Since both are incorporeal, they are weightless.</p><p>Wraiths speak Common and Infernal.</p><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><p>Both the wraith and the dread wraith share the following abilities.</p><div topic=\"Unnatural Aura\" level=\"8\"><p><b>Unnatural Aura (Su):</b> Animals, whether wild or domesticated, can sense the unnatural presence of a wraith at a distance of 30 feet. They will not willingly approach nearer than that and panic if forced to do so; they remain panicked as long as they are within that range.</p>\n</div><div topic=\"Daylight Powerlessness\" level=\"8\"><p><b>Daylight Powerlessness (Ex):</b> Wraiths are utterly powerless in natural sunlight (not merely a <i>daylight</i> spell) and flee from it.</p>\n</div>\n</div><div topic=\"Wraith\" level=\"3\"><p><h3>Wraith</h3></p><div topic=\"Constitution Drain\" level=\"8\"><p><b>Constitution Drain (Su):</b> Living creatures hit by a wraith\'s incorporeal touch attack must succeed on a DC 14 Fortitude save or take 1d6 points of Constitution drain. The save DC is Charisma-based. On each such successful attack, the wraith gains 5 temporary hit points.</p>\n</div><div topic=\"Create Spawn\" level=\"8\"><p><b>Create Spawn (Su):</b> Any humanoid slain by a wraith becomes a wraith in 1d4 rounds. Its body remains intact and inanimate, but its spirit is torn free from its corpse and transformed. Spawn are under the command of the wraith that created them and remain enslaved until its death. They do not possess any of the abilities they had in life.</p>\n</div>\n</div><div topic=\"Dread Wraith\" level=\"3\"><p><h3>Dread Wraith</h3></p><p>The oldest and most malevolent wraiths lurk in the depths of forgotten temples and other forsaken places. They can sense the approach of living creatures, and hunger for them. Despite its size, the dread wraith possesses unearthly quickness, and makes use of its Spring Attack feat and natural reach to strike with deadly effect and melt back into the shadows-or the walls.</p><div topic=\"Lifesense\" level=\"8\"><p><b>Lifesense (Su):</b> A dread wraith notices and locates living creatures within 60 feet, just as if it possessed the blindsight ability. It also senses the strength of their life force automatically, as if it had cast <i>deathwatch</i>.</p>\n</div><div topic=\"Constitution Drain\" level=\"8\"><p><b>Constitution Drain (Su):</b> Living creatures hit by a dread wraith\'s incorporeal touch attack must succeed on a DC 25 Fortitude save or take 1d8 points of Constitution drain. The save DC is Charisma-based. On each such successful attack, the dread wraith gains 5 temporary hit points.</p>\n</div><div topic=\"Create Spawn\" level=\"8\"><p><b>Create Spawn (Su):</b> Any humanoid slain by a dread wraith becomes a wraith in 1d4 rounds. Its body remains intact and inanimate, but its spirit is torn free from its corpse and transformed. Spawn are under the command of the wraith that created them and remain enslaved until its death. They do not possess any of the abilities they had in life.</p><p/>\n</div>\n</div>\n</div>\n    ','SRD 3.5 MonstersT-Z');
INSERT INTO monster VALUES (601,'Wraith','Dread Wraith',NULL,'Large','Undead','Incorporeal','16d12 (104 hp)','+13','Fly 60 ft. (good) (12 squares)','25 (-1 size, +9 Dex, +7 deflection), touch 25, flat-footed 16','+8','-','Incorporeal touch +16 melee (2d6 plus 1d8 Constitution drain)','Incorporeal touch +16 melee (2d6 plus 1d8 Constitution drain)','10 ft.','10 ft.','Constitution drain, create spawn','Darkvision 60 ft., daylight powerlessness, incorporeal traits, lifesense 60 ft., undead traits, unnatural aura','Fort +5, Ref +14, Will +14','Str -, Dex 28, Con -, Int 17, Wis 18, Cha 24','Diplomacy +9, Hide +24, Intimidate +26, Knowledge (religion) +22, Listen +25, Search +22, Sense Motive +23, Spot +25, Survival +4 (+6 following tracks)','Alertness, Improved Initiative','Blind-Fight, Combat Reflexes, Dodge, Improved Natural Attack (incorporeal touch), Mobility, Spring Attack',NULL,'Any','Solitary','11','None','Always lawful evil','17-32 HD (Large)','-','Constitution Drain (Su), Create Spawn (Su), Daylight Powerlessness (Ex), Lifesense (Su), Unnatural Aura (Su)','Dread wraith; CR 11; Large undead (incorporeal); HD 16d12; hp 104; Init +13; Spd Fly 60 ft. (good) (12 squares); AC 25 (-1 size, +9 dex, +7 deflection), touch 25, flat-footed 16; Base Atk +8; Grp -; Atk +16 melee (2d6 plus 1d8 Constitution drain, incorporeal touch); Full Atk +16 melee (2d6 plus 1d8 Constitution drain, incorporeal touch); Space/Reach 10 ft./10 ft.; SA Constitution drain, create spawn; SQ Darkvision 60 ft., daylight powerlessness, incorporeal traits, lifesense 60 ft., undead traits, unnatural aura; AL LE; SV Fort +5, Ref +14, Will +14; Str -, Dex 28, Con -, Int 17, Wis 18, Cha 24\n\nSkills and Feats: Diplomacy +9, Hide +24, Intimidate +26, Knowledge (religion) +22, Listen +25, Search +22, Sense Motive +23, Spot +25, Survival +4 (+6 following tracks); Alertness, Blind-Fight, Combat Reflexes, Dodge, Improved Initiative, Improved Natural Attack (incorporeal touch), Mobility, Spring Attack','\n      <div topic=\"Wraith\" level=\"2\"><p><h2>Wraith</h2></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n\n<td><b>Dread Wraith</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n\n<td>Large Undead (Incorporeal)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n\n<td>16d12 (104 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n\n<td>+13<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n\n<td>Fly 60 ft. (good) (12 squares)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n\n<td>25 (-1 size, +9 Dex, +7 deflection), touch 25, flat-footed 16<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n\n<td>+8/-<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n\n<td>Incorporeal touch +16 melee (2d6 plus 1d8 Constitution drain)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n\n<td>Incorporeal touch +16 melee (2d6 plus 1d8 Constitution drain)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n\n<td>10 ft./10 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n\n<td>Constitution drain, create spawn<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n\n<td>Darkvision 60 ft., daylight powerlessness, incorporeal traits, lifesense 60 ft., undead traits, unnatural aura<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n\n<td>Fort +5, Ref +14, Will +14<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n\n<td>Str -, Dex 28, Con -, Int 17, Wis 18, Cha 24<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n\n<td>Diplomacy +9, Hide +24, Intimidate +26, Knowledge (religion) +22, Listen +25, Search +22, Sense Motive +23, Spot +25, Survival +4 (+6 following tracks)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n\n<td>Alertness <sup>B</sup>, Blind-Fight, Combat Reflexes, Dodge, Improved Initiative <sup>B</sup>, Improved Natural Attack (incorporeal touch), Mobility, Spring Attack<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n\n<td>Any<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n\n<td>Solitary<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n\n<td>11<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n\n<td>None<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n\n<td>Always lawful evil<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n\n<td>17-32 HD (Large)<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n\n<td>-<br/></td>\n\n</tr>\n</table><p>Wraiths are incorporeal creatures born of evil and darkness. In some cases, the grim silhouette of a wraith might appear armored or outfitted with weapons. This appearance does not affect the creature\'s AC or combat abilities but only reflects the shape it had in life.</p><p>A wraith is about as tall as a human, while a dread wraith is roughly the size of an ogre. Since both are incorporeal, they are weightless.</p><p>Wraiths speak Common and Infernal.</p><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><p>Both the wraith and the dread wraith share the following abilities.</p><div topic=\"Unnatural Aura\" level=\"8\"><p><b>Unnatural Aura (Su):</b> Animals, whether wild or domesticated, can sense the unnatural presence of a wraith at a distance of 30 feet. They will not willingly approach nearer than that and panic if forced to do so; they remain panicked as long as they are within that range.</p>\n</div><div topic=\"Daylight Powerlessness\" level=\"8\"><p><b>Daylight Powerlessness (Ex):</b> Wraiths are utterly powerless in natural sunlight (not merely a <i>daylight</i> spell) and flee from it.</p>\n</div>\n</div><div topic=\"Wraith\" level=\"3\"><p><h3>Wraith</h3></p><div topic=\"Constitution Drain\" level=\"8\"><p><b>Constitution Drain (Su):</b> Living creatures hit by a wraith\'s incorporeal touch attack must succeed on a DC 14 Fortitude save or take 1d6 points of Constitution drain. The save DC is Charisma-based. On each such successful attack, the wraith gains 5 temporary hit points.</p>\n</div><div topic=\"Create Spawn\" level=\"8\"><p><b>Create Spawn (Su):</b> Any humanoid slain by a wraith becomes a wraith in 1d4 rounds. Its body remains intact and inanimate, but its spirit is torn free from its corpse and transformed. Spawn are under the command of the wraith that created them and remain enslaved until its death. They do not possess any of the abilities they had in life.</p>\n</div>\n</div><div topic=\"Dread Wraith\" level=\"3\"><p><h3>Dread Wraith</h3></p><p>The oldest and most malevolent wraiths lurk in the depths of forgotten temples and other forsaken places. They can sense the approach of living creatures, and hunger for them. Despite its size, the dread wraith possesses unearthly quickness, and makes use of its Spring Attack feat and natural reach to strike with deadly effect and melt back into the shadows-or the walls.</p><div topic=\"Lifesense\" level=\"8\"><p><b>Lifesense (Su):</b> A dread wraith notices and locates living creatures within 60 feet, just as if it possessed the blindsight ability. It also senses the strength of their life force automatically, as if it had cast <i>deathwatch</i>.</p>\n</div><div topic=\"Constitution Drain\" level=\"8\"><p><b>Constitution Drain (Su):</b> Living creatures hit by a dread wraith\'s incorporeal touch attack must succeed on a DC 25 Fortitude save or take 1d8 points of Constitution drain. The save DC is Charisma-based. On each such successful attack, the dread wraith gains 5 temporary hit points.</p>\n</div><div topic=\"Create Spawn\" level=\"8\"><p><b>Create Spawn (Su):</b> Any humanoid slain by a dread wraith becomes a wraith in 1d4 rounds. Its body remains intact and inanimate, but its spirit is torn free from its corpse and transformed. Spawn are under the command of the wraith that created them and remain enslaved until its death. They do not possess any of the abilities they had in life.</p><p/>\n</div>\n</div>\n</div>\n    ','SRD 3.5 MonstersT-Z');
INSERT INTO monster VALUES (602,'Wyvern','Wyvern',NULL,'Large','Dragon',NULL,'7d12+14 (59 hp)','+1','20 ft. (4 squares), fly 60 ft. (poor)','18 (-1 size, +1 Dex, +8 natural), touch 10, flat-footed 17','+7','+15','Sting +10 melee (1d6+4 plus poison) or talon +10 melee (2d6+4) or bite +10 melee (2d8+4)','Sting +10 melee (1d6+4 plus poison) and bite +8 melee (2d8+4) and 2 wings +8 melee (1d8+2) and 2 talons +8 melee (2d6+4)','10 ft.','5 ft.','Poison, improved grab','Darkvision 60 ft., immunity to sleep and paralysis, low-light vision, scent','Fort +7, Ref +6, Will +6','Str 19, Dex 12, Con 15, Int 6, Wis 12, Cha 9','Hide +7, Listen +13, Move Silently +11, Spot +16','Multiattack','Ability Focus (poison), Alertness, Flyby Attack',NULL,'Warm hills','Solitary, pair, or flight (3-6)','6','Standard','Usually neutral','8-10 HD (Huge); 11-21 HD (Gargantuan)','-','Improved Grab (Ex), Poison (Ex)','Wyvern; CR 6; Large dragon; HD 7d12+14; hp 59; Init +1; Spd 20 ft. (4 squares), fly 60 ft. (poor); AC 18 (-1 size, +1 dex, +8 natural), touch 10, flat-footed 17; Base Atk +7; Grp +15; Atk +10 melee (1d6+4 plus poison, sting) or +10 melee (2d6+4, talon) or +10 melee (2d8+4, bite); Full Atk +10 melee (1d6+4 plus poison, sting) and +8 melee (2d8+4, bite) and +8 melee (1d8+2, 2 wings) and +8 melee (2d6+4, 2 talons); Space/Reach 10 ft./5 ft.; SA Poison, improved grab; SQ Darkvision 60 ft., immunity to sleep and paralysis, low-light vision, scent; AL N; SV Fort +7, Ref +6, Will +6; Str 19, Dex 12, Con 15, Int 6, Wis 12, Cha 9\n\nSkills and Feats: Hide +7, Listen +13, Move Silently +11, Spot +16; Ability Focus (poison), Alertness, Flyby Attack, Multiattack','\n      <div topic=\"Wyvern\" level=\"2\"><p><h2>Wyvern</h2></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td><b>Wyvern</b><br/></td>\n\n</tr><tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Large Dragon<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>7d12+14 (59 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>+1<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>20 ft. (4 squares), fly 60 ft. (poor)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>18 (-1 size, +1 Dex, +8 natural), touch 10, flat-footed 17<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+7/+15<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>Sting +10 melee (1d6+4 plus poison) or talon +10 melee (2d6+4) or bite +10 melee (2d8+4)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>Sting +10 melee (1d6+4 plus poison) and bite +8 melee (2d8+4) and 2 wings +8 melee (1d8+2) and 2 talons +8 melee (2d6+4)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>10 ft./5 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>Poison, improved grab<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>Darkvision 60 ft., immunity to <i>sleep</i> and paralysis, low-light vision, scent<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +7, Ref +6, Will +6<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str 19, Dex 12, Con 15, Int 6, Wis 12, Cha 9<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n<td>Hide +7, Listen +13, Move Silently +11, Spot +16<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>Ability Focus (poison), Alertness, Flyby Attack, Multiattack <sup>B</sup><br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>Warm hills<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Solitary, pair, or flight (3-6)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>6<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n<td>Standard<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n<td>Usually neutral<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>8-10 HD (Huge); 11-21 HD (Gargantuan)<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>-<br/></td>\n\n</tr>\n</table><p>A distant cousin to the true dragons, the wyvern is a huge flying lizard with a poisonous stinger in its tail.</p><p>A wyvern\'s body is 15 feet long, and dark brown to gray; half that length is tail. Its wingspan is about 20 feet. A wyvern weighs about one ton.</p><p>Wyverns speak Draconic, but usually don\'t bother with anything more elaborate than a loud hiss or a deep-throated growl much like that of a bull alligator.</p><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><p>Wyverns are rather stupid but always aggressive: They attack nearly anything that isn\'t obviously more powerful than themselves. A wyvern dives from the air, snatching the opponent with its talons and stinging it to death. A wyvern can slash with its talons only when making a flyby attack.</p><div topic=\"Improved Grab\" level=\"8\"><p><b>Improved Grab (Ex):</b> To use this ability, a wyvern must hit with its talons. It can then attempt to start a grapple as a free action without provoking an attack of opportunity. If it wins the grapple check, it establishes a hold and stings.</p>\n</div><div topic=\"Poison\" level=\"8\"><p><b>Poison (Ex):</b> Injury, Fortitude DC 17, initial and secondary damage 2d6 Con. The save DC is Constitution-based.</p>\n</div><div topic=\"Skills\" level=\"8\"><p><b>Skills:</b> Wyverns have a +3 racial bonus on Spot checks.</p><p/>\n</div>\n</div>\n</div>\n    ','SRD 3.5 MonstersT-Z');
INSERT INTO monster VALUES (603,'Xill','Xill',NULL,'Medium','Outsider','Extraplanar','5d8+10 (32 hp)','+7','40 ft. (8 squares)','20 (+3 Dex, +7 natural), touch 13, flat-footed 17','+5','+7','Short sword +7 melee (1d6+2/19-20) or claw +7 melee (1d4+2) or longbow +8 ranged (1d8/x3)','2 short swords +5 melee (1d6+2/19-20, 1d6+1/19-20) and 2 claws +5 melee (1d4+1); or 4 claws +5 melee (1d4+2, 1d4+1); or 2 longbows +4 ranged (1d8/x3)','5 ft.','5 ft.','Implant, improved grab, paralysis','Darkvision 60 ft., planewalk, spell resistance 21','Fort +6, Ref +7, Will +5','Str 15, Dex 16, Con 15, Int 12, Wis 12, Cha 11','Balance +13, Climb +10, Diplomacy +2, Escape Artist +11, Intimidate +8, Listen +9, Move Silently +11, Sense Motive +8, Spot +9, Tumble +11, Use Rope +3 (+5 with bindings)','Multiattack','Improved Initiative, Multiweapon Fighting',NULL,'Ethereal Plane','Solitary or gang (2-5)','6','Standard','Always lawful evil','6-8 HD (Medium); 9-15 HD (Large)','+4','Implant (Ex), Improved Grab (Ex), Paralysis (Ex), Planewalk (Su)','Xill; CR 6; Medium outsider (extraplanar); HD 5d8+10; hp 32; Init +7; Spd 40 ft. (8 squares); AC 20 (+3 dex, +7 natural), touch 13, flat-footed 17; Base Atk +5; Grp +7; Atk +7 melee (1d6+2/19-20, short sword) or +7 melee (1d4+2, claw) or +8 ranged (1d8/x3, longbow); Full Atk +5 melee (1d6+2/19-20, 1d6+1/19-20, 2 short swords) and +5 melee (1d4+1, 2 claws) or +5 melee (1d4+2, 1d4+1, 4 claws) or +4 ranged (1d8/x3, 2 longbows); Space/Reach 5 ft./5 ft.; SA Implant, improved grab, paralysis; SQ Darkvision 60 ft., planewalk, spell resistance 21; AL LE; SV Fort +6, Ref +7, Will +5; Str 15, Dex 16, Con 15, Int 12, Wis 12, Cha 11\n\nSkills and Feats: Balance +13, Climb +10, Diplomacy +2, Escape Artist +11, Intimidate +8, Listen +9, Move Silently +11, Sense Motive +8, Spot +9, Tumble +11, Use Rope +3 (+5 with bindings); Improved Initiative, Multiattack, Multiweapon Fighting','\n      <div topic=\"Xill\" level=\"2\"><p><h2>Xill</h2></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td><b>Xill</b><br/></td> \n</tr><tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Medium Outsider (Extraplanar)<br/></td> \n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>5d8+10 (32 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>+7<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>40 ft. (8 squares)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>20 (+3 Dex, +7 natural), touch 13, flat-footed 17<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Base Attack/Grapple:</b><br/></td>\n<td>+5/+7<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>Short sword +7 melee (1d6+2/19-20) or claw +7 melee (1d4+2) or longbow +8 ranged (1d8/x3)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>2 short swords +5 melee (1d6+2/19-20, 1d6+1/19-20) and 2 claws +5 melee (1d4+1); or 4 claws +5 melee (1d4+2, 1d4+1); or 2 longbows +4 ranged (1d8/x3)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>5 ft./5 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>Implant, improved grab, paralysis<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>Darkvision 60 ft., planewalk, spell resistance 21<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +6, Ref +7, Will +5<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str 15, Dex 16, Con 15, Int 12, Wis 12, Cha 11<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n<td>Balance +13, Climb +10, Diplomacy +2, Escape Artist +11, Intimidate +8, Listen +9, Move Silently +11, Sense Motive +8, Spot +9, Tumble +11, Use Rope +3 (+5 with bindings)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>Improved Initiative, Multiattack <sup>B</sup>, Multiweapon Fighting<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>Ethereal Plane<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Solitary or gang (2-5)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>6<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n<td>Standard<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n<td>Always lawful evil<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>6-8 HD (Medium); 9-15 HD (Large)<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>+4<br/></td>\n\n</tr>\n</table><p>A xill stands 4 to 5 feet tall and weighs about 100 pounds. Xills speak Infernal.</p><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><p>Xills are dangerous opponents, attacking with all four limbs. More civilized ones use weapons, usually fighting with two at a time so as to leave two claws free for grab attacks. Xills typically lie in wait on the Ethereal Plane for suitable prey to happen by, then ambush it using their planewalk ability. They make full use of their Tumble skill in combat: Usually, one or two distract physically powerful enemies by attacking, then assuming a defensive stance while their fellows maneuver to advantage.</p><div topic=\"Implant\" level=\"8\"><p><b>Implant (Ex):</b> As a standard action, a xill can lay eggs inside a paralyzed creature. The young emerge about 90 days later, literally devouring the host from inside. A <i>remove disease</i> spell rids a victim of the egg, as does a DC 25 Heal check. If the check fails, the healer can try again, but each attempt (successful or not) deals 1d4 points of damage to the patient.</p>\n</div><div topic=\"Improved Grab\" level=\"8\"><p><b>Improved Grab (Ex):</b> To use this ability, a xill must hit with one or more claw attacks. It can then attempt to start a grapple as a free action without provoking an attack of opportunity. It receives a +2 bonus on the grapple check for each claw that hits. If it wins the grapple check and maintains the hold in the next round, it automatically bites the foe at that time. The bite deals no damage but injects a paralyzing venom.</p>\n</div><div topic=\"Paralysis\" level=\"8\"><p><b>Paralysis (Ex):</b> Those bitten by a xill must succeed on a DC 14 Fortitude save or be paralyzed for 1d4 hours. The save DC is Constitution-based.</p>\n</div><div topic=\"Planewalk\" level=\"8\"><p><b>Planewalk (Su):</b> These planar travelers like to slip between the folds of space to attack enemies as though from thin air. They can cross from the Ethereal Plane with a move action but take 2 rounds to cross back, during which time they are immobile. As a xill fades away, it becomes harder to hit: Opponents have a 20% miss chance in the first round and a 50% miss chance in the second. A xill can planewalk with a willing or helpless creature.</p><p/>\n</div>\n</div>\n</div>\n    ','SRD 3.5 MonstersT-Z');
INSERT INTO monster VALUES (604,'Xorn','Minor Xorn',NULL,'Small','Outsider','Extraplanar, Earth','3d8+9 (22 hp)','+0','20 ft. (4 squares), burrow 20 ft.','23 (+1 size, +12 natural), touch 11, flat-footed 23',NULL,NULL,'Bite +6 melee (2d8+2)','Bite +6 melee (2d8+2) and 3 claws +4 melee (1d3+1)','5 ft.','5 ft.','-','All-around vision, earth glide, damage reduction 5/bludgeoning, darkvision 60 ft., immunity to cold and fire, electricity resistance 10, tremorsense 60 ft.','Fort +5, Ref +3, Will +3','Str 15, Dex 10, Con 15, Int 10, Wis 11, Cha 10','Hide +10, Intimidate +3, Knowledge (dungeoneering) +6, Listen +6, Move Silently +3, Search +6, Spot +8, Survival +6 (+8 following tracks or underground)',NULL,'Multiattack, Toughness',NULL,'Elemental Plane of Earth','Solitary, pair, or cluster (3-5)','3','None','Usually neutral','4-6 HD (Small)','-','All-Around Vision (Ex), Earth Glide (Ex)','Minor xorn; CR 3; Small outsider (extraplanar, earth); HD 3d8+9; hp 22; Init +0; Spd 20 ft. (4 squares), burrow 20 ft.; AC 23 (+1 size, +12 natural), touch 11, flat-footed 23; Base Atk ; Atk +6 melee (2d8+2, bite); Full Atk +6 melee (2d8+2, bite) and +4 melee (1d3+1, 3 claws); Space/Reach 5 ft./5 ft.; SA -; SQ All-around vision, earth glide, damage reduction 5/bludgeoning, darkvision 60 ft., immunity to cold and fire, electricity resistance 10, tremorsense 60 ft.; AL N; SV Fort +5, Ref +3, Will +3; Str 15, Dex 10, Con 15, Int 10, Wis 11, Cha 10\n\nSkills and Feats: Hide +10, Intimidate +3, Knowledge (dungeoneering) +6, Listen +6, Move Silently +3, Search +6, Spot +8, Survival +6 (+8 following tracks or underground); Multiattack, Toughness','\n      <div topic=\"Xorn\" level=\"2\"><p><h2>Xorn</h2></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td><b>Minor Xorn</b><br/></td> \n\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n<td>Small Outsider (Extraplanar, Earth)<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n<td>3d8+9 (22 hp)<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n<td>+0<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n<td>20 ft. (4 squares), burrow 20 ft.<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n<td>23 (+1 size, +12 natural), touch 11, flat-footed 23<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n<td>Bite +6 melee (2d8+2)<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n<td>Bite +6 melee (2d8+2) and 3 claws +4 melee (1d3+1)<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n<td>5 ft./5 ft.<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n<td>-<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n<td>All-around vision, earth glide, damage reduction 5/bludgeoning, darkvision 60 ft., immunity to cold and fire, electricity resistance 10, tremorsense 60 ft.<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n<td>Fort +5, Ref +3, Will +3<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n<td>Str 15, Dex 10, Con 15, Int 10, Wis 11, Cha 10<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n<td>Hide +10, Intimidate +3, Knowledge (dungeoneering) +6, Listen +6, Move Silently +3, Search +6, Spot +8, Survival +6 (+8 following tracks or underground)<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n<td>Multiattack, Toughness<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n<td>Elemental Plane of Earth<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n<td>Solitary, pair, or cluster (3-5)<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n<td>3<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n<td>None<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n<td>Usually neutral<br/></td>\n\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n<td>4-6 HD (Small)<br/></td>\n\n\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n<td>-<br/></td>\n\n\n\n</tr>\n</table><p>Minor xorns are about 3 feet tall and wide and weigh about 120 pounds. Average xorns are about 5 feet tall and wide, weighing about 600 pounds. Elder xorns are about 8 feet tall and wide and weigh about 9,000 pounds.</p><p>Xorns speak Common and Terran.</p><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><p>Xorns do not attack fleshly beings except to defend themselves or their property, since they cannot digest meat. Xorns are indifferent to creatures of the Material Plane-with the sole exception of anyone carrying a significant amount of precious metals or minerals, which xorns eat. They can smell food up to 20 feet away. A xorn can be quite aggressive when seeking food, especially on the Material Plane, where such sustenance is harder to find than it is on its native plane.</p><p>A xorn\'s favorite mode of attack is to wait just beneath a stone surface until a foe comes within reach, then emerge suddenly. Groups of xorns often send one of their number to the surface to negotiate for food while the remainder position themselves for a surprise attack.</p><div topic=\"All-Around Vision\" level=\"8\"><p><b>All-Around Vision (Ex):</b> A xorn\'s symmetrically placed eyes allow it to look in any direction, providing a +4 racial bonus on Spot and Search checks. A xorn can\'t be flanked.</p>\n</div><div topic=\"Earth Glide\" level=\"8\"><p><b>Earth Glide (Ex):</b> A xorn can glide through stone, dirt, or almost any other sort of earth except metal as easily as a fish swims through water. Its burrowing leaves behind no tunnel or hole, nor does it create any ripple or other signs of its presence. A <i>move earth</i> spell cast on an area containing a burrowing xorn flings the xorn back 30 feet, stunning the creature for 1 round unless it succeeds on a DC 15 Fortitude save.</p><p/>\n</div>\n</div>\n</div>\n    ','SRD 3.5 MonstersT-Z');
INSERT INTO monster VALUES (605,'Xorn','Average Xorn',NULL,'Medium','Outsider','Extraplanar, Earth','7d8+17 (48 hp)','+0','20 ft. (4 squares), burrow 20 ft.','24 (+14 natural), touch 10, flat-footed 24',NULL,NULL,'Bite +10 melee (4d6+3)','Bite +10 melee (4d6+3) and 3 claws +8 melee (1d4+1)','5 ft.','5 ft.','-','All-around vision, earth glide, damage reduction 5/bludgeoning, darkvision 60 ft., immunity to cold and fire, electricity resistance 10, tremorsense 60 ft.','Fort +7, Ref +5, Will +5','Str 17, Dex 10, Con 15, Int 10, Wis 11, Cha 10','Hide +10, Intimidate +10, Knowledge(dungeoneering) +10, Listen +10, Move Silently +10, Search +10, Spot +10, Survival+10 (+12 following tracks or underground)','Cleave','Multiattack, Power Attack, Toughness',NULL,'Elemental Plane of Earth','Solitary, pair, or cluster (3-5)','6','None','Usually neutral','8-14 HD (Medium)','-','All-Around Vision (Ex), Earth Glide (Ex)','Average xorn; CR 6; Medium outsider (extraplanar, earth); HD 7d8+17; hp 48; Init +0; Spd 20 ft. (4 squares), burrow 20 ft.; AC 24 (+14 natural), touch 10, flat-footed 24; Base Atk ; Atk +10 melee (4d6+3, bite); Full Atk +10 melee (4d6+3, bite) and +8 melee (1d4+1, 3 claws); Space/Reach 5 ft./5 ft.; SA -; SQ All-around vision, earth glide, damage reduction 5/bludgeoning, darkvision 60 ft., immunity to cold and fire, electricity resistance 10, tremorsense 60 ft.; AL N; SV Fort +7, Ref +5, Will +5; Str 17, Dex 10, Con 15, Int 10, Wis 11, Cha 10\n\nSkills and Feats: Hide +10, Intimidate +10, Knowledge(dungeoneering) +10, Listen +10, Move Silently +10, Search +10, Spot +10, Survival+10 (+12 following tracks or underground); Cleave, Multiattack, Power Attack, Toughness','\n      <div topic=\"Xorn\" level=\"2\"><p><h2>Xorn</h2></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n <td><b>Average Xorn</b><br/></td>\n\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n\n<td>Medium Outsider (Extraplanar, Earth)<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n\n<td>7d8+17 (48 hp)<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n\n<td>+0<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n\n<td>20 ft. (4 squares), burrow 20 ft.<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n\n<td>24 (+14 natural), touch 10, flat-footed 24<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Attack:</b><br/></td>\n\n<td>Bite +10 melee (4d6+3)<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Full Attack:</b><br/></td>\n\n<td>Bite +10 melee (4d6+3) and 3 claws +8 melee (1d4+1)<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Space/Reach:</b><br/></td>\n\n<td>5 ft./5 ft.<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Attacks:</b><br/></td>\n\n<td>-<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Special Qualities:</b><br/></td>\n\n<td>All-around vision, earth glide, damage reduction 5/bludgeoning, darkvision 60 ft., immunity to cold and fire, electricity resistance 10, tremorsense 60 ft.<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Saves:</b><br/></td>\n\n<td>Fort +7, Ref +5, Will +5<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Abilities:</b><br/></td>\n\n<td>Str 17, Dex 10, Con 15, Int 10, Wis 11, Cha 10<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Skills:</b><br/></td>\n\n<td>Hide +10, Intimidate +10, Knowledge(dungeoneering) +10, Listen +10, Move Silently +10, Search +10, Spot +10, Survival+10 (+12 following tracks or underground)<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Feats:</b><br/></td>\n\n<td>Cleave <sup>B</sup>, Multiattack, Power Attack, Toughness<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Environment:</b><br/></td>\n\n<td>Elemental Plane of Earth<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Organization:</b><br/></td>\n\n<td>Solitary, pair, or cluster (3-5)<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Challenge Rating:</b><br/></td>\n\n<td>6<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Treasure:</b><br/></td>\n\n<td>None<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Alignment:</b><br/></td>\n\n<td>Usually neutral<br/></td>\n\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Advancement:</b><br/></td>\n\n<td>8-14 HD (Medium)<br/></td>\n\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Level Adjustment:</b><br/></td>\n\n<td>-<br/></td>\n\n\n</tr>\n</table><p>Minor xorns are about 3 feet tall and wide and weigh about 120 pounds. Average xorns are about 5 feet tall and wide, weighing about 600 pounds. Elder xorns are about 8 feet tall and wide and weigh about 9,000 pounds.</p><p>Xorns speak Common and Terran.</p><div topic=\"Combat\" level=\"5\"><p><h5>Combat</h5></p><p>Xorns do not attack fleshly beings except to defend themselves or their property, since they cannot digest meat. Xorns are indifferent to creatures of the Material Plane-with the sole exception of anyone carrying a significant amount of precious metals or minerals, which xorns eat. They can smell food up to 20 feet away. A xorn can be quite aggressive when seeking food, especially on the Material Plane, where such sustenance is harder to find than it is on its native plane.</p><p>A xorn\'s favorite mode of attack is to wait just beneath a stone surface until a foe comes within reach, then emerge suddenly. Groups of xorns often send one of their number to the surface to negotiate for food while the remainder position themselves for a surprise attack.</p><div topic=\"All-Around Vision\" level=\"8\"><p><b>All-Around Vision (Ex):</b> A xorn\'s symmetrically placed eyes allow it to look in any direction, providing a +4 racial bonus on Spot and Search checks. A xorn can\'t be flanked.</p>\n</div><div topic=\"Earth Glide\" level=\"8\"><p><b>Earth Glide (Ex):</b> A xorn can glide through stone, dirt, or almost any other sort of earth except metal as easily as a fish swims through water. Its burrowing leaves behind no tunnel or hole, nor does it create any ripple or other signs of its presence. A <i>move earth</i> spell cast on an area containing a burrowing xorn flings the xorn back 30 feet, stunning the creature for 1 round unless it succeeds on a DC 15 Fortitude save.</p><p/>\n</div>\n</div>\n</div>\n    ','SRD 3.5 MonstersT-Z');
INSERT INTO monster VALUES (606,'Xorn','Elder Xorn',NULL,'Large','Outsider','Extraplanar, Earth','15d8+63 (130 hp)','+0','20 ft. (4 squares), burrow 20 ft.','25 (-1 size, +16 natural), touch 9, flat-footed 25',NULL,NULL,'Bite +21 melee (4d8+7)','Bite +21 melee (4d8+7) and 3 claws +19 melee (1d6+3)','10 ft.','10 ft.','-','All-around vision, earth glide, damage reduction 5/bludgeoning, darkvision 60 ft., immunity to cold and fire, electricity resistance 10, tremorsense 60 ft.','Fort +13, Ref +9, Will +9','Str 25, Dex 10, Con 19, Int 10, Wis 11, Cha 10','Hide +14, Intimidate +18, Knowledge (dungeoneering) +18, Listen +18, Move Silently +18, Search +22, Spot +22, Survival+18 (+20 following tracks or underground)','Cleave','Awesome Blow, Great Cleave, Improved Bull Rush, Multiattack, Power Attack, Toughness',NULL,'Elemental Plane of Earth','Solitary, pair, or party (6-11)','8','None','Usually neutral','16-21 HD (Large); 22-45 HD (Huge)','-','All-Around Vision (Ex), Earth Glide (Ex)','Elder xorn; CR 8; Large outsider (extraplanar, earth); HD 15d8+63; hp 130; Init +0; Spd 20 ft. (4 squares), burrow 20 ft.; AC 25 (-1 size, +16 natural), touch 9, flat-footed 25; Base Atk ; Atk +21 melee (4d8+7, bite); Full Atk +21 melee (4d8+7, bite) and +19 melee (1d6+3, 3 claws); Space/Reach 10 ft./10 ft.; SA -; SQ All-around vision, earth glide, damage reduction 5/bludgeoning, darkvision 60 ft., immunity to cold and fire, electricity resistance 10, tremorsense 60 ft.; AL N; SV Fort +13, Ref +9, Will +9; Str 25, Dex 10, Con 19, Int 10, Wis 11, Cha 10\n\nSkills and Feats: Hide +14, Intimidate +18, Knowledge (dungeoneering) +18, Listen +18, Move Silently +18, Search +22, Spot +22, Survival+18 (+20 following tracks or underground); Awesome Blow, Cleave, Great Cleave, Improved Bull Rush, Multiattack, Power Attack, Toughness','\n      <div topic=\"Xorn\" level=\"2\"><p><h2>Xorn</h2></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n \n<td><b>Elder Xorn</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td/>\n\n\n<td>Large Outsider (Extraplanar, Earth)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Hit Dice:</b><br/></td>\n\n\n<td>15d8+63 (130 hp)<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Initiative:</b><br/></td>\n\n\n<td>+0<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Speed:</b><br/></td>\n\n\n<td>20 ft. (4 squares), burrow 20 ft.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Armor Class:</b><br/></td>\n\n\n<td>25 (-1 size, +16 natural), touch 9, flat-footed 25<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">